<script setup lang="ts">
import { AlertCircle, CloudOff, Inbox } from "@lucide/vue";
const props = withDefaults(defineProps<{ variant?: "empty" | "error" | "offline"; title: string; description?: string }>(), { variant: "empty", description: "" });
const icon = computed(() => props.variant === "error" ? AlertCircle : props.variant === "offline" ? CloudOff : Inbox);
</script>
<template><section class="app-state" :class="`app-state--${variant}`" :role="variant === 'error' ? 'alert' : 'status'"><span class="app-state__icon"><component :is="icon" :size="30" aria-hidden="true" /></span><h2>{{ title }}</h2><p v-if="description">{{ description }}</p><div v-if="$slots.primary || $slots.secondary" class="app-state__actions"><slot name="primary" /><slot name="secondary" /></div></section></template>
<style scoped>.app-state { display: grid; justify-items: center; align-content: center; gap: var(--space-3); min-height: 280px; padding: var(--space-8) var(--space-6); color: var(--color-text-primary); text-align: center; }.app-state__icon { display: grid; place-items: center; width: 64px; height: 64px; border: 1px solid var(--color-border); border-radius: var(--radius-pill); background: var(--color-surface); }.app-state--error .app-state__icon { color: var(--color-danger); }.app-state--offline .app-state__icon { color: var(--color-warning); }.app-state h2,.app-state p { margin: 0; }.app-state h2 { font-size: var(--font-size-heading); }.app-state p { max-width: 420px; color: var(--color-text-secondary); font-size: var(--font-size-body-sm); line-height: 1.6; }.app-state__actions { display: flex; flex-wrap: wrap; justify-content: center; gap: var(--space-2); margin-top: var(--space-2); }</style>
